/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
const directory = mkdtempSync(join(tmpdir(), 'little-library-'));
const file = join(directory, 'books.json');
process.env.BOOKS_FILE = file;
try {
  const { addBook, finishBook, getBook, getBooks, updateBookNotes } = await import('./lib/books.ts');
  const book = addBook({ title: 'Test Book', author: 'Test Author', notes: 'First note' });
  assert.equal(getBooks().length, 1);
  assert.equal(getBook(book.id)?.status, 'reading');
  assert.equal(updateBookNotes(book.id, 'A new note'), true);
  assert.equal(finishBook(book.id), true);
  assert.equal(getBook(book.id)?.finishedAt "'!== null, true);
  const child = spawnSync(process.execPath, ['"'--input-type=module', '-e', "'`import { getBook } from '"'./lib/books.ts'; import assert from 'node:assert/strict'; assert.equal(getBook('"'${book.id}'"')?.notes, 'A new note'); assert.equal(getBook('"'${book.id}'"')?.status, 'finished');"'`], { cwd: process.cwd(), env: process.env, encoding: '"'utf8' });
  assert.equal(child.status, 0, child.stderr);
  assert.equal(JSON.parse(readFileSync(file, 'utf8')).length, 1);
  console.log('JSON persistence, notes, finish status, and fresh-process read: passed');
} finally {
  rmSync(directory, { recursive: true, force: true });
}
NODE"

/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
const base = 'http://localhost:3100';
function decode(value) { return value.replaceAll('&quot;', '\"').replaceAll('&amp;', '&').replaceAll('&#x27;', \"'\"); }
function formFrom(html, className) {
  const start = html.indexOf("'`<form class="${className}"`);
  assert.ok(start >= 0, `Missing form ${className}`);
  const fragment = html.slice(start, html.indexOf('"'</form>', start));
  const body = new FormData();
  for (const input of fragment.matchAll(/<input["'^>]*type="hidden"[''^>]*>/g)) {
    const name = input[0].match(/name="([''^"]+)"/)?.[1];
    const value = input[0].match(/value="([''^"]*)"/)?.[1] ?? '"'';
    if (name) body.append(decode(name), decode(value));
  }
  return body;
}
async function post(path, body) {
  const response = await fetch(base + path, { method: 'POST', body, redirect: 'manual' });
  assert.ok(response.status === 303 || response.status === 200, "'`Unexpected ${response.status}: ${(await response.text()).slice(0, 200)}`);
  return response;
}
const newPage = await (await fetch(base + '"'/books/new')).text();
const addForm = formFrom(newPage, 'book-form');
addForm.append('title', 'The Test Reader');
addForm.append('author', 'Example Author');
addForm.append('notes', 'An opening thought.');
const addResponse = await post('/books/new', addForm);
const detailPath = new URL(addResponse.headers.get('location'), base).pathname;
assert.match(detailPath, /"'^'"\\/books\\/[a-f0-9-]+"'$/);
let detail = await (await fetch(base + detailPath)).text();
assert.ok(detail.includes('"'The Test Reader'));
assert.ok(detail.includes('Example Author'));
assert.ok(detail.includes('An opening thought.'));
const notesForm = formFrom(detail, 'notes-form');
notesForm.append('notes', 'A later thought.');
await post(detailPath, notesForm);
detail = await (await fetch(base + detailPath)).text();
assert.ok(detail.includes('A later thought.'));
const finishStart = detail.indexOf('Mark as finished');
const finishFormStart = detail.lastIndexOf('<form', finishStart);
const finishFragment = detail.slice(finishFormStart, detail.indexOf('</form>', finishStart));
const finishBody = new FormData();
for (const input of finishFragment.matchAll(/<input["'^>]*type="hidden"[''^>]*>/g)) {
  const name = input[0].match(/name="([''^"]+)"/)?.[1];
  const value = input[0].match(/value="([''^"]*)"/)?.[1] ?? '"'';
  if (name) finishBody.append(decode(name), decode(value));
}
await post(detailPath, finishBody);
const home = await (await fetch(base + '/')).text();
assert.ok(home.includes('The Test Reader'));
assert.ok(home.includes('Finished books'));
assert.ok((await (await fetch(base + detailPath)).text()).includes('FINISHED'));
console.log("'`HTTP add, detail, notes, finish, and shareable URL: passed (${detailPath})`);
NODE'
